import{_ as e,o as t,c as o,al as n}from"./chunks/framework.BawR2jEz.js";const u=JSON.parse('{"title":"Файловый менеджер","description":"Загрузка, просмотр и управление файлами на сервере через встроенный файловый менеджер exDoc.","frontmatter":{"title":"Файловый менеджер","description":"Загрузка, просмотр и управление файлами на сервере через встроенный файловый менеджер exDoc."},"headers":[],"relativePath":"file-manager/index.md","filePath":"file-manager/index.md"}'),s={name:"file-manager/index.md"};function i(r,a,l,d,c,p){return t(),o("div",null,[...a[0]||(a[0]=[n(`<h1 id="фаиловыи-менеджер" tabindex="-1">Файловый менеджер <a class="header-anchor" href="#фаиловыи-менеджер" aria-label="Permalink to &quot;Файловый менеджер&quot;">​</a></h1><p>Файловый менеджер exDoc позволяет загружать, просматривать и управлять файлами на сервере прямо из админ-панели.</p><h2 id="доступ" tabindex="-1">Доступ <a class="header-anchor" href="#доступ" aria-label="Permalink to &quot;Доступ&quot;">​</a></h2><p>Файловый менеджер доступен:</p><ul><li>Через иконку в <strong>верхнем меню</strong> админ-панели</li><li>При выборе файла в полях типа <code>image</code>, <code>file_list</code> и др.</li></ul><h2 id="интерфеис" tabindex="-1">Интерфейс <a class="header-anchor" href="#интерфеис" aria-label="Permalink to &quot;Интерфейс&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────┬─────────────────────────────────┐</span></span>
<span class="line"><span>│                │                                 │</span></span>
<span class="line"><span>│  Дерево        │  Содержимое директории          │</span></span>
<span class="line"><span>│  директорий    │                                 │</span></span>
<span class="line"><span>│                │  ┌────┐  ┌────┐  ┌────┐         │</span></span>
<span class="line"><span>│  📁 catalog    │  │ 📄 │  │ 📄 │  │ 📄 │         │</span></span>
<span class="line"><span>│    📁 images   │  │file│  │file│  │file│         │</span></span>
<span class="line"><span>│    📁 docs     │  └────┘  └────┘  └────┘         │</span></span>
<span class="line"><span>│  📁 upload     │                                 │</span></span>
<span class="line"><span>│                │                                 │</span></span>
<span class="line"><span>└────────────────┴─────────────────────────────────┘</span></span></code></pre></div><h3 id="дерево-директории-treedirectory" tabindex="-1">Дерево директорий (TreeDirectory) <a class="header-anchor" href="#дерево-директории-treedirectory" aria-label="Permalink to &quot;Дерево директорий (TreeDirectory)&quot;">​</a></h3><p>Левая панель отображает иерархию папок. Клик по папке открывает её содержимое в правой панели.</p><h3 id="содержимое-директории-contentdirectory" tabindex="-1">Содержимое директории (ContentDirectory) <a class="header-anchor" href="#содержимое-директории-contentdirectory" aria-label="Permalink to &quot;Содержимое директории (ContentDirectory)&quot;">​</a></h3><p>Правая панель показывает файлы и подпапки выбранной директории:</p><ul><li><strong>Папки</strong> — отображаются иконками с именем</li><li><strong>Файлы</strong> — отображаются с превью (для изображений) или иконкой типа файла</li></ul><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><h3 id="загрузка-фаилов" tabindex="-1">Загрузка файлов <a class="header-anchor" href="#загрузка-фаилов" aria-label="Permalink to &quot;Загрузка файлов&quot;">​</a></h3><p>Загрузка файлов на сервер в текущую выбранную директорию.</p><h3 id="создание-папки" tabindex="-1">Создание папки <a class="header-anchor" href="#создание-папки" aria-label="Permalink to &quot;Создание папки&quot;">​</a></h3><p>Создание новой директории внутри текущей.</p><h3 id="переименование" tabindex="-1">Переименование <a class="header-anchor" href="#переименование" aria-label="Permalink to &quot;Переименование&quot;">​</a></h3><p>Переименование файла или папки без перемещения.</p><h3 id="удаление" tabindex="-1">Удаление <a class="header-anchor" href="#удаление" aria-label="Permalink to &quot;Удаление&quot;">​</a></h3><p>Удаление выбранных файлов и папок.</p><h3 id="правка-текстового-фаила" tabindex="-1">Правка текстового файла <a class="header-anchor" href="#правка-текстового-фаила" aria-label="Permalink to &quot;Правка текстового файла&quot;">​</a></h3><p>Двойной клик по файлу открывает его содержимое в редакторе прямо в менеджере — можно поправить и сохранить на место, не заходя на сервер по FTP.</p><p>Открываются только текстовые форматы: <code>txt</code>, <code>md</code>, <code>json</code>, <code>xml</code>, <code>css</code>, <code>scss</code>, <code>js</code>, <code>twig</code>, <code>php</code>, <code>.htaccess</code>. По остальным двойной клик просто выделяет файл: изображение или архив в текстовом редакторе показали бы мусор, а сохранение испортило бы файл.</p><p>Когда менеджер открыт из поля, двойной клик означает другое — выбрать файл и вернуть путь в поле.</p><h3 id="поиск-по-директории" tabindex="-1">Поиск по директории <a class="header-anchor" href="#поиск-по-директории" aria-label="Permalink to &quot;Поиск по директории&quot;">​</a></h3><p>Поле поиска над содержимым отбирает файлы <strong>текущей</strong> директории по части имени. По вложенным папкам поиск не идёт, и регистр важен: запрос <code>photo</code> не найдёт <code>Photo.jpg</code>.</p><h3 id="выбор-фаила" tabindex="-1">Выбор файла <a class="header-anchor" href="#выбор-фаила" aria-label="Permalink to &quot;Выбор файла&quot;">​</a></h3><p>При использовании файлового менеджера из поля (например, поле <code>image</code>), клик по файлу выбирает его и возвращает путь в поле.</p><h2 id="что-можно-загрузить" tabindex="-1">Что можно загрузить <a class="header-anchor" href="#что-можно-загрузить" aria-label="Permalink to &quot;Что можно загрузить&quot;">​</a></h2><p>Через менеджер загружаются только растровые изображения:</p><table tabindex="0"><thead><tr><th>Формат</th><th>Расширение</th></tr></thead><tbody><tr><td>JPEG</td><td><code>jpg</code>, <code>jpeg</code></td></tr><tr><td>PNG</td><td><code>png</code></td></tr><tr><td>GIF</td><td><code>gif</code></td></tr></tbody></table><p>Проверяется и расширение, и настоящий тип содержимого файла — переименовать <code>.php</code> в <code>.jpg</code> и загрузить не получится.</p><p>Ограничение размера берётся из настроек OpenCart — <strong>Система → Настройки → Сервер → Максимальный размер файла</strong>, отдельной настройки у exDoc нет.</p><p>Показывает менеджер больше, чем принимает: SVG, WebP и любые другие файлы, попавшие на сервер иным путём, видны в списке и доступны для выбора в полях. Не загружаются они намеренно — SVG умеет нести внутри себя скрипт, а произвольные файлы через админку не заливаются вовсе.</p><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="./../fields/">Поля</a> — поля типа <a href="./../fields/image/">image</a>, <a href="./../fields/image-list/">image_list</a>, <a href="./../fields/file-list/">file_list</a></li><li><a href="./../fast-settings/svg-sprites.html">SVG-спрайты</a> — управление SVG-иконками</li></ul>`,37)])])}const f=e(s,[["render",i]]);export{u as __pageData,f as default};
